def leaves(v,path=""):
 if isinstance(v,dict) and v:
  for k,w in v.items(): yield from leaves(w,path+"/"+k)
 elif isinstance(v,list) and v:
  for i,w in enumerate(v): yield from leaves(w,path+"/"+str(i))
 else: yield path,v
